//! Integration tests for the PE/COFF reader (`qld::coff::read`, workstream
//! W14).
//!
//! Prebuilt fixtures under `tests/data/coff_read/` (regenerated by
//! `generate.sh` there) are checked on every host against known contents.
//! When `llvm-readobj` is installed, everything qld parses is also compared
//! with its output. Further tests compile fresh objects with MinGW GCC and
//! clang, and build import libraries and a DLL with `llvm-dlltool`,
//! `dlltool` and `windres`; each skips (passes with a `SKIPPED:` line) when
//! a tool is missing. Set `QLD_REQUIRE_COFF_TOOLS=1` to make a missing tool
//! fail instead.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;

use qld::coff::read::consts::{
    self, IMAGE_COMDAT_SELECT_ANY, IMAGE_COMDAT_SELECT_ASSOCIATIVE, IMAGE_FILE_MACHINE_AMD64,
    IMAGE_FILE_MACHINE_ARM64, IMAGE_FILE_MACHINE_I386, IMAGE_SUBSYSTEM_WINDOWS_GUI,
    IMAGE_SYM_CLASS_FILE, IMAGE_WEAK_EXTERN_SEARCH_ALIAS, IMPORT_NAME_EXPORTAS,
};
use qld::coff::read::{
    AuxFunctionDefinition, AuxSectionDefinition, AuxWeakExternal, CoffFile, CoffObject, Directive,
    ExportTarget, ImportName, LongImportDlls, LongImportMember, PeImage, ShortImport, Source,
    Symbol, classify_long_import, parse_module_definition,
};
use qld::input::archive::Archive;
use qld::target::Architecture;

// ---------------------------------------------------------------------------
// Files and tools
// ---------------------------------------------------------------------------

fn data_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/coff_read")
}

fn fixture(name: &str) -> (PathBuf, Vec<u8>) {
    let path = data_dir().join(name);
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    (path, data)
}

fn scratch_dir(test: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("coff_read")
        .join(test);
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Reports a skipped check, or fails when `QLD_REQUIRE_COFF_TOOLS` is set.
fn skip(reason: &str) {
    if std::env::var_os("QLD_REQUIRE_COFF_TOOLS").is_some_and(|v| !v.is_empty() && v != "0") {
        panic!("required tool unavailable: {reason}");
    }
    println!("SKIPPED: {reason}");
}

/// Runs `tool` and returns its standard output, or `None` (after saying
/// why) if it cannot be run or fails.
fn run(tool: &str, args: &[&str]) -> Option<String> {
    match Command::new(tool).args(args).output() {
        Ok(output) if output.status.success() => {
            Some(String::from_utf8_lossy(&output.stdout).into_owned())
        }
        Ok(output) => {
            skip(&format!(
                "`{tool} {}` failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&output.stderr).trim()
            ));
            None
        }
        Err(error) => {
            skip(&format!("{tool} unavailable: {error}"));
            None
        }
    }
}

/// Runs a command that must create `out`; returns its contents.
fn build(tool: &str, args: &[&str], out: &Path) -> Option<Vec<u8>> {
    run(tool, args)?;
    match std::fs::read(out) {
        Ok(data) => Some(data),
        Err(error) => {
            skip(&format!("{tool} did not write {}: {error}", out.display()));
            None
        }
    }
}

fn path_str(path: &Path) -> &str {
    path.to_str().expect("UTF-8 path")
}

fn text(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

fn source(path: &Path) -> Source<'_> {
    Source::new(path)
}

// ---------------------------------------------------------------------------
// Inventory: what qld reads from an object, in readobj's vocabulary
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
struct Sec {
    number: u32,
    name: String,
    virtual_size: u64,
    virtual_address: u64,
    raw_size: u64,
    pointer_to_raw_data: u64,
    pointer_to_relocations: u64,
    relocation_count: u64,
    characteristics: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Rel {
    section: u32,
    offset: u64,
    kind: String,
    symbol: String,
    index: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Sym {
    name: String,
    value: u64,
    section: i64,
    base_type: u64,
    complex_type: u64,
    storage_class: u64,
    aux_count: u64,
    /// `(record kind, [(key, value)])`, values normalized as in
    /// [`normalize`].
    aux: Vec<(String, Vec<(String, String)>)>,
}

#[derive(Debug, Default, Clone, PartialEq, Eq)]
struct Inventory {
    header: Vec<(String, String)>,
    sections: Vec<Sec>,
    relocations: Vec<Rel>,
    symbols: Vec<Sym>,
}

fn pairs(items: &[(&str, String)]) -> Vec<(String, String)> {
    items
        .iter()
        .map(|(k, v)| ((*k).to_owned(), v.clone()))
        .collect()
}

/// The aux records of `symbol`, decoded the way `llvm-readobj` chooses to
/// decode them.
fn aux_records(symbol: &Symbol<'_>) -> Vec<(String, Vec<(String, String)>)> {
    let mut records = Vec::new();
    for i in 0..symbol.number_of_aux_symbols {
        let raw = symbol.aux_record(i).expect("aux record");
        if symbol.is_function_definition() {
            let def = AuxFunctionDefinition::decode(raw).unwrap();
            records.push((
                "AuxFunctionDef".to_owned(),
                pairs(&[
                    ("TagIndex", def.tag_index.to_string()),
                    ("TotalSize", def.total_size.to_string()),
                    ("PointerToLineNumber", def.pointer_to_linenumber.to_string()),
                    (
                        "PointerToNextFunction",
                        def.pointer_to_next_function.to_string(),
                    ),
                ]),
            ));
        } else if symbol.is_undefined() || symbol.is_weak_external() {
            let weak = AuxWeakExternal::decode(raw).unwrap();
            records.push((
                "AuxWeakExternal".to_owned(),
                pairs(&[
                    ("Linked", weak.tag_index.to_string()),
                    ("Search", weak.characteristics.to_string()),
                ]),
            ));
        } else if symbol.is_file() {
            records.push((
                "AuxFileRecord".to_owned(),
                pairs(&[("FileName", text(symbol.file_name().unwrap()))]),
            ));
            break;
        } else if symbol.is_section_definition() {
            let def = AuxSectionDefinition::decode(raw, symbol.bigobj).unwrap();
            let mut fields = pairs(&[
                ("Length", def.length.to_string()),
                ("RelocationCount", def.number_of_relocations.to_string()),
                ("LineNumberCount", def.number_of_linenumbers.to_string()),
                ("Checksum", def.check_sum.to_string()),
                ("Number", def.number.to_string()),
                ("Selection", def.selection.to_string()),
            ]);
            if let Some(section) = def.associative_section() {
                fields.push(("AssocSection".to_owned(), section.to_string()));
            }
            records.push(("AuxSectionDef".to_owned(), fields));
        }
    }
    records
}

fn object_inventory(object: &CoffObject<'_>) -> Inventory {
    let header = object.header();
    let mut inventory = Inventory {
        header: pairs(&[
            ("Machine", u64::from(header.machine).to_string()),
            ("SectionCount", header.number_of_sections.to_string()),
            (
                "PointerToSymbolTable",
                header.pointer_to_symbol_table.to_string(),
            ),
            ("SymbolCount", header.number_of_symbols.to_string()),
            (
                "StringTableSize",
                object.symbols().strings().len().to_string(),
            ),
            (
                "OptionalHeaderSize",
                header.size_of_optional_header.to_string(),
            ),
            ("Characteristics", header.characteristics.to_string()),
        ]),
        ..Inventory::default()
    };
    for section in object.sections() {
        let section = section.unwrap();
        let h = section.header;
        inventory.sections.push(Sec {
            number: section.number,
            name: text(section.name),
            virtual_size: h.virtual_size.into(),
            virtual_address: h.virtual_address.into(),
            raw_size: h.size_of_raw_data.into(),
            pointer_to_raw_data: h.pointer_to_raw_data.into(),
            pointer_to_relocations: h.pointer_to_relocations.into(),
            relocation_count: h.number_of_relocations.into(),
            characteristics: h.characteristics.into(),
        });
        object.section_data(&h).unwrap();
        for reloc in object.relocations(&h).unwrap().iter() {
            let symbol = object.symbol(reloc.symbol_table_index).unwrap();
            inventory.relocations.push(Rel {
                section: section.number,
                offset: reloc.virtual_address.into(),
                kind: consts::relocation_name(object.machine(), reloc.r_type)
                    .expect("known relocation type")
                    .to_owned(),
                symbol: text(symbol.name),
                index: reloc.symbol_table_index.into(),
            });
        }
    }
    for symbol in object.symbols().iter() {
        let symbol = symbol.unwrap();
        inventory.symbols.push(Sym {
            name: text(symbol.name),
            value: symbol.value.into(),
            section: symbol.section_number.into(),
            base_type: symbol.base_type().into(),
            complex_type: symbol.complex_type().into(),
            storage_class: symbol.storage_class.into(),
            aux_count: symbol.number_of_aux_symbols.into(),
            aux: aux_records(&symbol),
        });
    }
    inventory
}

// ---------------------------------------------------------------------------
// llvm-readobj output
// ---------------------------------------------------------------------------

/// A line of `llvm-readobj` output and the lines nested under it.
#[derive(Debug, Default)]
struct Node {
    head: String,
    children: Vec<Node>,
}

impl Node {
    fn value(&self, key: &str) -> Option<&str> {
        self.children.iter().find_map(|c| {
            let rest = c.head.strip_prefix(key)?.strip_prefix(':')?;
            Some(rest.strip_prefix(' ').unwrap_or(rest))
        })
    }

    fn get(&self, key: &str) -> &str {
        self.value(key)
            .unwrap_or_else(|| panic!("no `{key}` under `{}`", self.head))
    }

    fn scopes<'s>(&'s self, name: &'s str) -> impl Iterator<Item = &'s Node> + 's {
        self.children
            .iter()
            .filter(move |c| c.head == name || c.head.starts_with(&format!("{name} ")))
    }

    fn scope<'s>(&'s self, name: &'s str) -> Option<&'s Node> {
        self.scopes(name).next()
    }
}

fn parse_tree(output: &str) -> Node {
    let mut stack = vec![Node::default()];
    for line in output.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if line == "}" || line == "]" {
            let node = stack.pop().expect("balanced output");
            stack
                .last_mut()
                .expect("balanced output")
                .children
                .push(node);
        } else if let Some(head) = line.strip_suffix(" {").or_else(|| line.strip_suffix(" [")) {
            stack.push(Node {
                head: head.to_owned(),
                children: Vec::new(),
            });
        } else if let Some((head, flags)) = line.split_once(" [ (") {
            // `Characteristics [ (0x60500020)` opens a flag list.
            stack.push(Node {
                head: format!("{head}: {}", flags.trim_end_matches(')')),
                children: Vec::new(),
            });
        } else {
            stack.last_mut().unwrap().children.push(Node {
                head: line.to_owned(),
                children: Vec::new(),
            });
        }
    }
    assert_eq!(stack.len(), 1, "unbalanced readobj output");
    stack.pop().unwrap()
}

/// Normalizes a readobj value: `Name (0x3)` and `name (24)` become the
/// number in parentheses, `0x1A` becomes decimal, other text is kept.
fn normalize(value: &str) -> String {
    let number = value
        .strip_suffix(')')
        .and_then(|v| v.rsplit_once('(').map(|(_, n)| n))
        .unwrap_or(value);
    let parsed = if let Some(hex) = number.strip_prefix("0x") {
        u64::from_str_radix(hex, 16).ok().map(|n| n.to_string())
    } else if let Some(hex) = number.strip_prefix("-0x") {
        i64::from_str_radix(hex, 16).ok().map(|n| (-n).to_string())
    } else {
        number.parse::<i64>().ok().map(|n| n.to_string())
    };
    parsed.unwrap_or_else(|| value.to_owned())
}

fn number(value: &str) -> i64 {
    normalize(value)
        .parse()
        .unwrap_or_else(|_| panic!("not a number: {value:?}"))
}

fn unumber(value: &str) -> u64 {
    u64::try_from(number(value)).unwrap()
}

/// Reads the flag-list head `Characteristics: 0x...`.
fn flags(node: &Node) -> u64 {
    let head = node
        .children
        .iter()
        .find(|c| c.head.starts_with("Characteristics: "))
        .expect("Characteristics");
    unumber(head.head.trim_start_matches("Characteristics: "))
}

fn readobj_inventory(root: &Node) -> Inventory {
    let mut inventory = Inventory::default();
    if let Some(header) = root.scope("ImageFileHeader") {
        let machine = header.get("Machine");
        let mut fields = vec![("Machine", unumber(machine).to_string())];
        for key in [
            "SectionCount",
            "PointerToSymbolTable",
            "SymbolCount",
            "StringTableSize",
            "OptionalHeaderSize",
        ] {
            fields.push((key, unumber(header.get(key)).to_string()));
        }
        fields.push(("Characteristics", flags(header).to_string()));
        inventory.header = pairs(&fields);
    }
    if let Some(sections) = root.scope("Sections") {
        for section in sections.scopes("Section") {
            let name = section.get("Name");
            let name = name.rsplit_once(" (").map_or(name, |(n, _)| n);
            inventory.sections.push(Sec {
                number: u32::try_from(unumber(section.get("Number"))).unwrap(),
                name: name.to_owned(),
                virtual_size: unumber(section.get("VirtualSize")),
                virtual_address: unumber(section.get("VirtualAddress")),
                raw_size: unumber(section.get("RawDataSize")),
                pointer_to_raw_data: unumber(section.get("PointerToRawData")),
                pointer_to_relocations: unumber(section.get("PointerToRelocations")),
                relocation_count: unumber(section.get("RelocationCount")),
                characteristics: flags(section),
            });
        }
    }
    if let Some(relocations) = root.scope("Relocations") {
        for section in relocations.scopes("Section") {
            // `Section (1) .text`
            let number = section
                .head
                .strip_prefix("Section (")
                .and_then(|h| h.split_once(')'))
                .map(|(n, _)| n.parse().unwrap())
                .unwrap();
            for line in &section.children {
                let (body, index) = line.head.rsplit_once(" (").unwrap();
                let mut parts = body.splitn(3, ' ');
                inventory.relocations.push(Rel {
                    section: number,
                    offset: unumber(parts.next().unwrap()),
                    kind: parts.next().unwrap().to_owned(),
                    symbol: parts.next().unwrap_or("").to_owned(),
                    index: unumber(index.trim_end_matches(')')),
                });
            }
        }
    }
    if let Some(symbols) = root.scope("Symbols") {
        for symbol in symbols.scopes("Symbol") {
            let aux = symbol
                .children
                .iter()
                .filter(|c| c.head.starts_with("Aux") && !c.head.contains(':'))
                .map(|record| {
                    let fields = record
                        .children
                        .iter()
                        .filter_map(|leaf| leaf.head.split_once(": "))
                        .map(|(k, v)| {
                            let v = if k == "FileName" {
                                v.to_owned()
                            } else {
                                normalize(v)
                            };
                            (k.to_owned(), v)
                        })
                        .collect();
                    (record.head.clone(), fields)
                })
                .collect();
            inventory.symbols.push(Sym {
                name: symbol.get("Name").to_owned(),
                value: unumber(symbol.get("Value")),
                section: number(symbol.get("Section")),
                base_type: unumber(symbol.get("BaseType")),
                complex_type: unumber(symbol.get("ComplexType")),
                storage_class: unumber(symbol.get("StorageClass")),
                aux_count: unumber(symbol.get("AuxSymbolCount")),
                aux,
            });
        }
    }
    inventory
}

fn readobj(args: &[&str], path: &Path) -> Option<String> {
    let mut all = args.to_vec();
    all.push(path_str(path));
    run("llvm-readobj", &all)
}

fn assert_same<T: std::fmt::Debug + PartialEq>(what: &str, path: &Path, ours: &[T], theirs: &[T]) {
    for (i, (a, b)) in ours.iter().zip(theirs).enumerate() {
        assert_eq!(a, b, "{}: {what} #{i} differs", path.display());
    }
    assert_eq!(
        ours.len(),
        theirs.len(),
        "{}: {what} count differs",
        path.display()
    );
}

/// Compares everything qld reads from an object with `llvm-readobj`.
/// Returns `false` (after a skip line) if `llvm-readobj` is missing.
fn compare_object_with_readobj(path: &Path, object: &CoffObject<'_>) -> bool {
    let Some(output) = readobj(
        &["--file-headers", "--sections", "--relocations", "--symbols"],
        path,
    ) else {
        return false;
    };
    let theirs = readobj_inventory(&parse_tree(&output));
    let ours = object_inventory(object);
    assert_same("header field", path, &ours.header, &theirs.header);
    assert_same("section", path, &ours.sections, &theirs.sections);
    assert_same("relocation", path, &ours.relocations, &theirs.relocations);
    assert_same("symbol", path, &ours.symbols, &theirs.symbols);

    if let Some(output) = readobj(&["--coff-directives"], path) {
        let raw: Vec<u8> = object
            .sections_named(b".drectve")
            .map(|s| {
                let s = s.unwrap();
                object.section_data(&s.header).unwrap().to_vec()
            })
            .next()
            .unwrap_or_default();
        let printed = output
            .lines()
            .find_map(|l| l.strip_prefix("Directive(s): "))
            .unwrap_or("");
        assert_eq!(
            text(&raw).trim_end_matches('\0'),
            printed.trim_end_matches('\0'),
            "{}: directives",
            path.display()
        );
    }
    true
}

// ---------------------------------------------------------------------------
// Helpers over parsed objects
// ---------------------------------------------------------------------------

fn parse_object<'a>(path: &'a Path, data: &'a [u8]) -> CoffObject<'a> {
    CoffObject::parse(data, source(path)).unwrap_or_else(|e| panic!("{e}"))
}

fn symbol<'a>(object: &CoffObject<'a>, name: &str) -> Symbol<'a> {
    object
        .symbols()
        .iter()
        .map(Result::unwrap)
        .find(|s| s.name == name.as_bytes())
        .unwrap_or_else(|| panic!("no symbol {name}"))
}

fn directives(object: &CoffObject<'_>) -> Vec<Directive<'static>> {
    let mut all = Vec::new();
    for section in object.directives() {
        for directive in section.unwrap() {
            all.push(into_owned(directive.unwrap()));
        }
    }
    all
}

fn owned(cow: std::borrow::Cow<'_, [u8]>) -> std::borrow::Cow<'static, [u8]> {
    std::borrow::Cow::Owned(cow.into_owned())
}

fn into_owned(directive: Directive<'_>) -> Directive<'static> {
    match directive {
        Directive::Export(spec) => Directive::Export(qld::coff::read::ExportSpec {
            name: owned(spec.name),
            internal_name: spec.internal_name.map(owned),
            import_name: spec.import_name.map(owned),
            export_as: spec.export_as.map(owned),
            ordinal: spec.ordinal,
            noname: spec.noname,
            data: spec.data,
            private: spec.private,
            constant: spec.constant,
        }),
        Directive::Include(name) => Directive::Include(owned(name)),
        Directive::DefaultLib(name) => Directive::DefaultLib(owned(name)),
        Directive::AlternateName { alias, target } => Directive::AlternateName {
            alias: owned(alias),
            target: owned(target),
        },
        Directive::AlignComm {
            symbol,
            alignment_log2,
        } => Directive::AlignComm {
            symbol: owned(symbol),
            alignment_log2,
        },
        other => Directive::Other {
            name: std::borrow::Cow::Owned(format!("{other:?}").into_bytes()),
            value: None,
        },
    }
}

fn export(name: &str, data: bool) -> Directive<'static> {
    Directive::Export(qld::coff::read::ExportSpec {
        name: std::borrow::Cow::Owned(name.as_bytes().to_vec()),
        data,
        ..Default::default()
    })
}

/// Checks the objects built from `mingw.c`.
fn check_mingw_object(object: &CoffObject<'_>) {
    assert_eq!(object.machine(), IMAGE_FILE_MACHINE_AMD64);
    assert_eq!(object.architecture(), Some(Architecture::X86_64));

    let file = object
        .symbols()
        .iter()
        .map(Result::unwrap)
        .find(|s| s.storage_class == IMAGE_SYM_CLASS_FILE)
        .expect(".file symbol");
    assert_eq!(file.file_name(), Some(&b"mingw.c"[..]));
    assert!(file.is_debug());

    let common = symbol(object, "common_symbol");
    assert!(common.is_common() && !common.is_undefined());
    assert_eq!(common.value, 4);

    let weak_ref = symbol(object, "weak_reference");
    assert!(weak_ref.is_weak_external());
    let aux = weak_ref.weak_external().expect("weak external aux");
    let default = object.symbol(aux.tag_index).unwrap();
    assert!(
        default.name.starts_with(b".weak.weak_reference."),
        "{default:?}"
    );

    let weak_def = symbol(object, "weak_definition");
    assert!(weak_def.is_weak_external());

    let local = symbol(object, "local_helper");
    assert_eq!(local.storage_class, consts::IMAGE_SYM_CLASS_STATIC);

    let long = object
        .sections()
        .map(Result::unwrap)
        .find(|s| s.name == b".custom_long_section_name")
        .expect("long section name");
    assert!(long.header.has_long_name());

    let refptr = object
        .sections()
        .map(Result::unwrap)
        .find(|s| s.name.starts_with(b".rdata$.refptr."))
        .expect("refptr COMDAT");
    assert!(refptr.header.is_comdat());
    assert!(refptr.header.alignment().is_some());
    let def = symbol(object, std::str::from_utf8(refptr.name).unwrap())
        .section_definition()
        .unwrap();
    assert_eq!(def.selection, IMAGE_COMDAT_SELECT_ANY);

    let text_section = object.section(1).unwrap();
    assert_eq!(text_section.name, b".text");
    assert!(text_section.header.is_code());
    assert_eq!(text_section.header.alignment(), Some(16));
    assert!(!object.relocations(&text_section.header).unwrap().is_empty());

    assert!(
        object
            .symbols()
            .iter()
            .any(|s| s.unwrap().name == b"__emutls_v.thread_local_value")
    );

    let found = directives(object);
    assert!(
        found.contains(&Directive::AlignComm {
            symbol: b"aligned_common".to_vec().into(),
            alignment_log2: 5
        }),
        "{found:?}"
    );
    assert!(
        found.contains(&export("exported_function", false)),
        "{found:?}"
    );
    assert!(found.contains(&export("exported_data", true)), "{found:?}");
    assert!(object.feat00().unwrap().is_none());
    assert!(object.addrsig().unwrap().is_none());
}

/// Checks the objects built from `msvc.cpp`.
fn check_msvc_object(object: &CoffObject<'_>, machine: u16) {
    assert_eq!(object.machine(), machine);
    assert!(!object.is_bigobj());
    let x86 = machine == IMAGE_FILE_MACHINE_I386;
    // `#pragma comment(linker)` text is copied verbatim, undecorated.
    let mangle = |name: &str| name.to_owned();

    let feat = object.feat00().unwrap().expect("@feat.00");
    assert!(feat.guard_cf());
    assert_eq!(feat.safe_seh(), x86);

    // Inline functions and template members are COMDAT sections selected
    // with ANY, with associative unwind data on x86-64 and ARM64.
    let mut comdat_leaders = 0;
    let mut associative = 0;
    for s in object.symbols().iter().map(Result::unwrap) {
        if let Some(def) = s.section_definition() {
            let section = object
                .section(u32::try_from(s.section_number).unwrap())
                .unwrap();
            if def.selection == IMAGE_COMDAT_SELECT_ANY && section.header.is_comdat() {
                comdat_leaders += 1;
            }
            if def.selection == IMAGE_COMDAT_SELECT_ASSOCIATIVE {
                associative += 1;
                let target = object.section(def.associative_section().unwrap()).unwrap();
                assert!(target.header.is_comdat(), "{}", text(target.name));
            }
        }
    }
    assert!(comdat_leaders >= 3, "COMDAT sections: {comdat_leaders}");
    assert_eq!(associative > 0, !x86, "associative sections: {associative}");

    let weak = symbol(object, "?weak_function@@YAHXZ");
    assert!(weak.is_weak_external());
    assert_eq!(
        weak.weak_external().unwrap().characteristics,
        IMAGE_WEAK_EXTERN_SEARCH_ALIAS
    );

    let tls = object
        .sections()
        .map(Result::unwrap)
        .find(|s| s.is_tls())
        .expect(".tls$ section");
    assert_eq!(tls.name, b".tls$");
    assert!(symbol(object, "?thread_value@@3HA").section_number > 0);

    let drectve = object.sections_named(b".drectve").next().unwrap().unwrap();
    assert!(drectve.header.is_info() && drectve.header.is_remove());
    let found = directives(object);
    let expected = [
        Directive::DefaultLib(b"fixturelib.lib".to_vec().into()),
        Directive::AlternateName {
            alias: mangle("alias_symbol").into_bytes().into(),
            target: mangle("real_symbol").into_bytes().into(),
        },
        Directive::Include(mangle("forced_symbol").into_bytes().into()),
        export("?exported_function@@YAHH@Z", false),
        export("?exported_data@@3HA", true),
    ];
    assert_eq!(found, expected);

    let addrsig: Vec<u32> = object
        .addrsig()
        .unwrap()
        .expect(".llvm_addrsig")
        .map(Result::unwrap)
        .collect();
    let names: Vec<_> = addrsig
        .iter()
        .map(|&i| text(object.symbol(i).unwrap().name))
        .collect();
    assert!(
        names.contains(&"?weak_function@@YAHXZ".to_owned())
            || names.iter().any(|n| n.contains("weak_function")),
        "{names:?}"
    );
}

