/// Short imports expected from `testlib.def`, as
/// `(symbol, import type, import name, dll-visible name type)`.
fn expected_short_imports(i386: bool) -> Vec<(String, u8, ImportName<'static>)> {
    let prefix = if i386 { "_" } else { "" };
    let name = |n: &'static str| ImportName::Name {
        hint: 0,
        name: n.as_bytes(),
    };
    vec![
        (format!("{prefix}plain_function"), 0, name("plain_function")),
        (format!("{prefix}plain_data"), 1, name("plain_data")),
        (format!("{prefix}by_ordinal"), 0, ImportName::Ordinal(7)),
        (format!("{prefix}public_name"), 0, name("public_name")),
        (format!("{prefix}constant_value"), 2, name("constant_value")),
        (format!("{prefix}hinted"), 0, name("hinted")),
        (format!("{prefix}exported_as"), 0, name("real_export")),
    ]
}

fn short_imports<'a>(path: &'a Path, data: &'a [u8]) -> Vec<ShortImport<'a>> {
    let archive = Archive::parse(path, data).unwrap();
    archive
        .members()
        .map(Result::unwrap)
        .filter_map(|member| {
            let bytes = member.bytes().unwrap();
            match CoffFile::parse(bytes, source(path)).unwrap() {
                CoffFile::ShortImport(import) => Some(import),
                CoffFile::Object(_) => None,
                CoffFile::Image(_) => panic!("image in an import library"),
            }
        })
        .collect()
}

#[test]
fn short_import_fixtures() {
    for (name, i386) in [
        ("short-import-x86_64.lib", false),
        ("short-import-i386.lib", true),
    ] {
        let (path, data) = fixture(name);
        let imports = short_imports(&path, &data);
        let expected = expected_short_imports(i386);
        assert_eq!(imports.len(), expected.len(), "{name}");
        for (import, (symbol, kind, import_name)) in imports.iter().zip(&expected) {
            assert_eq!(text(import.symbol_name), *symbol);
            assert_eq!(import.dll_name, b"testlib.dll");
            assert_eq!(import.import_type, *kind, "{symbol}");
            assert_eq!(import.defines_symbol_name(), *kind != 1);
            let expected_arch = if i386 {
                Architecture::X86
            } else {
                Architecture::X86_64
            };
            assert_eq!(import.architecture(), Some(expected_arch));
            match (import.import_name(), import_name) {
                (ImportName::Name { name, .. }, ImportName::Name { name: want, .. }) => {
                    assert_eq!(name, *want, "{symbol}");
                }
                (got, want) => assert_eq!(got, *want, "{symbol}"),
            }
            if import.name_type == IMPORT_NAME_EXPORTAS {
                assert_eq!(import.export_as, Some(&b"real_export"[..]));
            }
        }
        compare_short_imports_with_readobj(&path, &imports);
    }
}

fn name_type_name(name_type: u8) -> &'static str {
    match name_type {
        0 => "ordinal",
        1 => "name",
        2 => "noprefix",
        3 => "undecorate",
        4 => "export as",
        _ => "unknown",
    }
}

fn compare_short_imports_with_readobj(path: &Path, imports: &[ShortImport<'_>]) {
    let Some(output) = readobj(&[], path) else {
        return;
    };
    let mut theirs = Vec::new();
    for block in output.split("\nFile: ").skip(1) {
        if !block.contains("Format: COFF-import-file") {
            continue;
        }
        let mut entry = BTreeMap::new();
        let mut symbols = Vec::new();
        for line in block.lines() {
            if let Some(symbol) = line.strip_prefix("Symbol: ") {
                symbols.push(symbol.to_owned());
            } else if let Some((key, value)) = line.split_once(": ") {
                entry.insert(key.to_owned(), value.to_owned());
            }
        }
        theirs.push((entry, symbols));
    }
    assert_eq!(theirs.len(), imports.len(), "{}", path.display());
    for (import, (entry, symbols)) in imports.iter().zip(&theirs) {
        let kind = match import.import_type {
            0 => "code",
            1 => "data",
            _ => "const",
        };
        assert_eq!(entry["Type"], kind);
        assert_eq!(entry["Name type"], name_type_name(import.name_type));
        match import.import_name() {
            ImportName::Name { name, .. } => assert_eq!(entry["Export name"], text(name)),
            ImportName::Ordinal(_) => assert!(!entry.contains_key("Export name")),
        }
        let mut ours = vec![format!("__imp_{}", text(import.symbol_name))];
        if import.defines_symbol_name() {
            ours.push(text(import.symbol_name));
        }
        assert_eq!(&ours, symbols, "{}", path.display());
    }
}

/// Classifies every member of a long import library and resolves DLLs.
/// Returns `(symbol members as (public name, import, dll), heads, tails)`.
fn long_imports(path: &Path, data: &[u8]) -> (Vec<(String, String, String)>, usize, usize) {
    let archive = Archive::parse(path, data).unwrap();
    let members: Vec<_> = archive.members().map(Result::unwrap).collect();
    let objects: Vec<_> = members
        .iter()
        .map(|m| CoffObject::parse(m.bytes().unwrap(), source(path)).unwrap())
        .collect();
    let classified: Vec<_> = objects
        .iter()
        .map(|o| classify_long_import(o).unwrap())
        .collect();
    let mut dlls = LongImportDlls::new();
    let (mut heads, mut tails) = (0, 0);
    for member in classified.iter().flatten() {
        match member {
            LongImportMember::Head { .. } => heads += 1,
            LongImportMember::Tail { .. } => tails += 1,
            LongImportMember::Symbol(_) => {}
        }
        dlls.add(member);
    }
    let mut symbols = Vec::new();
    for member in classified.iter().flatten() {
        if let LongImportMember::Symbol(symbol) = member {
            let import = match symbol.import {
                ImportName::Name { name, .. } => text(name),
                ImportName::Ordinal(ordinal) => format!("#{ordinal}"),
            };
            let dll = dlls
                .dll_name(symbol.head_symbol)
                .map(text)
                .unwrap_or_else(|| "?".to_owned());
            symbols.push((text(symbol.symbol_name()), import, dll));
        }
    }
    symbols.sort();
    (symbols, heads, tails)
}

#[test]
fn long_import_fixture() {
    let (path, data) = fixture("long-import-x86_64.a");
    let (symbols, heads, tails) = long_imports(&path, &data);
    assert_eq!((heads, tails), (1, 1));
    assert_eq!(symbols, expected_long_imports());
}

/// Long imports GNU `dlltool` makes from `testlib.def`, as `(symbol,
/// import, dll)`. `dlltool` does not know LLVM's `EXPORTAS` keyword and
/// reads it and its argument as two more exports.
fn expected_long_imports() -> Vec<(String, String, String)> {
    let mut expected: Vec<_> = [
        ("EXPORTAS", "EXPORTAS"),
        ("by_ordinal", "#7"),
        ("constant_value", "constant_value"),
        ("exported_as", "exported_as"),
        ("hinted", "hinted"),
        ("plain_data", "plain_data"),
        ("plain_function", "plain_function"),
        ("public_name", "public_name"),
        ("real_export", "real_export"),
    ]
    .iter()
    .map(|(s, i)| ((*s).to_owned(), (*i).to_owned(), "testlib.dll".to_owned()))
    .collect();
    expected.sort();
    expected
}

