fn check_test_dll(image: &PeImage<'_>) {
    assert!(image.is_dll());
    assert!(image.is_pe32_plus());
    assert_eq!(image.machine(), IMAGE_FILE_MACHINE_AMD64);
    assert_eq!(image.architecture(), Some(Architecture::X86_64));
    assert_ne!(image.image_base(), 0);
    assert!(matches!(
        image.subsystem(),
        consts::IMAGE_SUBSYSTEM_WINDOWS_CUI | IMAGE_SUBSYSTEM_WINDOWS_GUI
    ));
    let exports = image.exports().unwrap().expect("export directory");
    assert_eq!(exports.dll_name, b"testdll.dll");
    assert_eq!(exports.ordinal_base, 1);
    let named: Vec<_> = exports.named().map(Result::unwrap).collect();
    let names: Vec<_> = named.iter().map(|e| text(e.name.unwrap())).collect();
    assert_eq!(
        names,
        ["dll_data", "dll_function", "dll_rodata", "forwarded_sleep"]
    );
    let by_name = |n: &str| named.iter().find(|e| e.name == Some(n.as_bytes())).unwrap();
    assert_eq!(by_name("dll_function").ordinal, 1);
    assert_eq!(
        by_name("forwarded_sleep").target,
        ExportTarget::Forwarder(b"kernel32.Sleep")
    );
    let ExportTarget::Rva(function) = by_name("dll_function").target else {
        panic!("dll_function is not an RVA")
    };
    let ExportTarget::Rva(data) = by_name("dll_data").target else {
        panic!("dll_data is not an RVA")
    };
    assert!(!image.is_data_rva(function));
    assert!(image.is_data_rva(data));
    let bytes = image.data_at_rva(data, 4).unwrap();
    assert_eq!(bytes, 42u32.to_le_bytes());

    let all = exports.all().unwrap();
    let hidden = all.iter().find(|e| e.ordinal == 5).expect("ordinal 5");
    assert_eq!(hidden.name, None);
    assert!(all.iter().all(|e| e.ordinal != 4), "unused slot listed");
}

fn compare_exports_with_readobj(path: &Path, image: &PeImage<'_>) {
    let Some(output) = readobj(&["--coff-exports"], path) else {
        return;
    };
    let root = parse_tree(&output);
    let mut theirs = Vec::new();
    for export in root.scopes("Export") {
        let name = export.get("Name");
        let target = match export.value("ForwardedTo") {
            Some(to) => format!("-> {to}"),
            None => {
                let rva = unumber(export.get("RVA"));
                if rva == 0 {
                    continue;
                }
                format!("{rva:#x}")
            }
        };
        theirs.push((unumber(export.get("Ordinal")), name.to_owned(), target));
    }
    let ours: Vec<_> = image
        .exports()
        .unwrap()
        .map(|dir| dir.all().unwrap())
        .unwrap_or_default()
        .into_iter()
        .map(|e| {
            let target = match e.target {
                ExportTarget::Rva(rva) => format!("{rva:#x}"),
                ExportTarget::Forwarder(to) => format!("-> {}", text(to)),
            };
            (
                u64::from(e.ordinal),
                e.name.map(text).unwrap_or_default(),
                target,
            )
        })
        .collect();
    assert_same("export", path, &ours, &theirs);
}

