#[test]
fn many_sections_bigobj() {
    // Enough COMDAT functions to need more than 65279 sections... is slow;
    // a few thousand exercise the 32-bit section numbers and the base64
    // long-name path as far as the assembler uses them.
    let dir = scratch_dir("many_sections");
    let src = dir.join("many.cpp");
    let mut code = String::new();
    for i in 0..3000 {
        code.push_str(&format!(
            "inline int function_with_a_long_name_{i}() {{ return {i}; }}\n\
             int use_{i}() {{ return function_with_a_long_name_{i}(); }}\n"
        ));
    }
    std::fs::write(&src, code).unwrap();
    let out = dir.join("many.o");
    let Some(data) = build(
        "x86_64-w64-mingw32-g++",
        &[
            "-c",
            "-O0",
            "-Wa,-mbig-obj",
            "-ffunction-sections",
            path_str(&src),
            "-o",
            path_str(&out),
        ],
        &out,
    ) else {
        return;
    };
    let object = parse_object(&out, &data);
    assert!(object.is_bigobj());
    assert!(object.section_count() > 6000, "{}", object.section_count());
    // Every associative section points at a COMDAT section.
    for s in object.symbols().iter().map(Result::unwrap) {
        if let Some(number) = s.section_definition().and_then(|d| d.associative_section()) {
            assert!(object.section(number).unwrap().header.is_comdat());
        }
    }
    compare_object_with_readobj(&out, &object);
}

