#[test]
fn mingw_dll_exports_match_readobj() {
    let dir = scratch_dir("mingw_dll");
    let out = dir.join("testdll.dll");
    let Some(data) = build(
        "x86_64-w64-mingw32-gcc",
        &[
            "-O1",
            "-shared",
            "-nostdlib",
            "-Wl,-e,DllMain",
            path_str(&data_dir().join("testdll.c")),
            path_str(&data_dir().join("testdll.def")),
            "-o",
            path_str(&out),
        ],
        &out,
    ) else {
        return;
    };
    let image = PeImage::parse(&data, source(&out)).unwrap();
    check_test_dll(&image);
    compare_exports_with_readobj(&out, &image);
    // Not stripped: GNU ld keeps a COFF symbol table and long section names.
    let names: Vec<_> = image.sections().map(|s| text(s.unwrap().name)).collect();
    assert!(names.contains(&".text".to_owned()), "{names:?}");

    // A full DLL with the C runtime.
    let out = dir.join("crt.dll");
    let src = dir.join("crt.c");
    std::fs::write(
        &src,
        "#include <stdio.h>\n__declspec(dllexport) int hello(void) { return puts(\"hi\"); }\n",
    )
    .unwrap();
    if let Some(data) = build(
        "x86_64-w64-mingw32-gcc",
        &["-g", "-shared", path_str(&src), "-o", path_str(&out)],
        &out,
    ) {
        let image = PeImage::parse(&data, source(&out)).unwrap();
        let exports = image.exports().unwrap().unwrap();
        assert!(exports.named().any(|e| e.unwrap().name == Some(b"hello")));
        compare_exports_with_readobj(&out, &image);
        let names: Vec<_> = image.sections().map(|s| text(s.unwrap().name)).collect();
        assert!(
            names.iter().any(|n| n.starts_with(".debug_")),
            "long section names resolved through the string table: {names:?}"
        );
    }
}

// ---------------------------------------------------------------------------
// Robustness
// ---------------------------------------------------------------------------

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn below(&mut self, n: usize) -> usize {
        usize::try_from(self.next() % (n.max(1) as u64)).unwrap()
    }
}

/// Walks everything a parser exposes; must not panic, whatever the bytes.
fn exercise(data: &[u8]) {
    let path = Path::new("fuzz");
    let src = source(path);
    match CoffFile::parse(data, src) {
        Ok(CoffFile::Object(object)) => exercise_object(&object),
        Ok(CoffFile::ShortImport(import)) => {
            let _ = import.import_name();
        }
        Ok(CoffFile::Image(image)) => {
            for section in image.sections().flatten() {
                let _ = image.section_data(&section.header);
            }
            for rva in [0, 0x1000, 0x2000, u32::MAX] {
                let _ = image.rva_to_file_offset(rva);
                let _ = image.c_string_at_rva(rva);
                let _ = image.is_data_rva(rva);
            }
            if let Ok(Some(exports)) = image.exports() {
                for export in exports.named().take(10_000) {
                    let _ = export;
                }
                let _ = exports.all();
            }
        }
        Err(_) => {}
    }
    let _ = CoffObject::parse(data, src).map(|o| exercise_object(&o));
    let _ = parse_module_definition(data, src);
    for directive in qld::coff::read::parse_directives(data, 0, src).take(10_000) {
        let _ = directive;
    }
}

fn exercise_object(object: &CoffObject<'_>) {
    for section in object.sections().take(100_000) {
        let Ok(section) = section else { continue };
        let _ = object.section_data(&section.header);
        if let Ok(relocs) = object.relocations(&section.header) {
            for reloc in relocs.iter().take(10_000) {
                let _ = object.symbol(reloc.symbol_table_index);
            }
        }
    }
    for symbol in object.symbols().iter().take(100_000).flatten() {
        let _ = (
            symbol.section_definition(),
            symbol.weak_external(),
            symbol.function_definition(),
            symbol.file_name(),
            symbol.aux_record(3),
        );
    }
    if let Some(directives) = object.directives().next()
        && let Ok(directives) = directives
    {
        for directive in directives.take(10_000) {
            let _ = directive;
        }
    }
    if let Ok(Some(addrsig)) = object.addrsig() {
        for index in addrsig.take(10_000) {
            let _ = index;
        }
    }
    let _ = object.feat00();
    let _ = classify_long_import(object);
    let _ = object.resource_sections().count();
}

fn corrupt_and_parse(data: &[u8], rounds: usize, seed: u64) {
    let mut rng = Rng(seed | 1);
    exercise(data);
    for len in 0..data.len().min(64) {
        exercise(&data[..len]);
    }
    for _ in 0..rounds {
        let mut mutated = data.to_vec();
        match rng.below(4) {
            0 => mutated.truncate(rng.below(data.len())),
            1 => {
                for _ in 0..1 + rng.below(8) {
                    let at = rng.below(mutated.len());
                    mutated[at] ^= 1 << rng.below(8);
                }
            }
            2 => {
                // Plant a large or boundary value in a 4-byte field.
                let at = rng.below(mutated.len().saturating_sub(4));
                let value: u32 = match rng.below(4) {
                    0 => u32::MAX,
                    1 => 0xffff,
                    2 => u32::try_from(rng.below(mutated.len() + 64)).unwrap(),
                    _ => rng.next() as u32,
                };
                if mutated.len() >= at + 4 {
                    mutated[at..at + 4].copy_from_slice(&value.to_le_bytes());
                }
            }
            _ => {
                let at = rng.below(mutated.len());
                let len = rng.below(mutated.len() - at);
                mutated.drain(at..at + len);
            }
        }
        exercise(&mutated);
    }
}

fn fixture_inputs() -> Vec<(String, Vec<u8>)> {
    let mut inputs = Vec::new();
    let mut names: Vec<_> = std::fs::read_dir(data_dir())
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .filter(|n| !n.ends_with(".sh"))
        .collect();
    names.sort();
    for name in names {
        let (path, data) = fixture(&name);
        if let Ok(archive) = Archive::parse(&path, &data) {
            for member in archive.members().map(Result::unwrap) {
                inputs.push((
                    format!("{name}({})", member.display_name()),
                    member.bytes().unwrap().to_vec(),
                ));
            }
        }
        inputs.push((name, data));
    }
    inputs
}

#[test]
fn corrupted_fixtures_do_not_panic() {
    let rounds = std::env::var("QLD_COFF_FUZZ_ROUNDS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(if cfg!(debug_assertions) { 300 } else { 3000 });
    for (i, (name, data)) in fixture_inputs().iter().enumerate() {
        let seed = 0x9e37_79b9_7f4a_7c15 ^ (i as u64).wrapping_mul(0x1234_5678_9abc_def1);
        let result = std::panic::catch_unwind(|| corrupt_and_parse(data, rounds, seed));
        assert!(result.is_ok(), "{name}: parser panicked");
    }
}

#[test]
fn random_text_does_not_panic() {
    let mut rng = Rng(0x5eed);
    let alphabet = b" \t\r\n\0\"'\\=,;@.-/:_abcXYZ0129EXPORTSLIBRARYDATANONAMEBASE";
    for _ in 0..2000 {
        let len = rng.below(80);
        let bytes: Vec<u8> = (0..len)
            .map(|_| alphabet[rng.below(alphabet.len())])
            .collect();
        exercise(&bytes);
    }
}

