/// Compares every COFF object member of the MinGW runtime archives (or of
/// the archives in `QLD_COFF_READOBJ_ARCHIVES`) with `llvm-readobj`.
#[test]
#[ignore = "slow: runs llvm-readobj over whole archives"]
fn sysroot_archives_match_readobj() {
    let archives: Vec<PathBuf> = match std::env::var_os("QLD_COFF_READOBJ_ARCHIVES") {
        Some(list) => std::env::split_paths(&list).collect(),
        None => {
            let Some(libgcc) = run("x86_64-w64-mingw32-gcc", &["-print-libgcc-file-name"]) else {
                return;
            };
            let mut list = vec![PathBuf::from(libgcc.trim())];
            for lib in ["libmingwex.a", "libmsvcrt.a", "libkernel32.a"] {
                if let Some(path) = run(
                    "x86_64-w64-mingw32-gcc",
                    &[&format!("-print-file-name={lib}")],
                ) {
                    list.push(PathBuf::from(path.trim()));
                }
            }
            list
        }
    };
    let mut members = 0;
    for path in archives.iter().filter(|p| p.is_file()) {
        let Some(output) = readobj(
            &["--file-headers", "--sections", "--relocations", "--symbols"],
            path,
        ) else {
            return;
        };
        let data = std::fs::read(path).unwrap();
        let archive = Archive::parse(path, &data).unwrap();
        let blocks: Vec<_> = output
            .split("\nFile: ")
            .skip(1)
            .filter(|b| !b.contains("Format: COFF-import-file"))
            .collect();
        let objects: Vec<_> = archive
            .members()
            .map(Result::unwrap)
            .filter_map(|m| m.bytes())
            .filter(|b| matches!(qld::input::identify(b), qld::input::FileFormat::Coff(_)))
            .collect();
        assert_eq!(blocks.len(), objects.len(), "{}", path.display());
        for (bytes, block) in objects.iter().zip(&blocks) {
            let object = CoffObject::parse(bytes, source(path)).unwrap();
            let theirs = readobj_inventory(&parse_tree(block));
            let ours = object_inventory(&object);
            assert_same("header field", path, &ours.header, &theirs.header);
            assert_same("section", path, &ours.sections, &theirs.sections);
            assert_same("relocation", path, &ours.relocations, &theirs.relocations);
            assert_same("symbol", path, &ours.symbols, &theirs.symbols);
            members += 1;
        }
        println!("{}: {} members match", path.display(), objects.len());
    }
    println!("{members} members compared");
}

#[derive(Debug, Default)]
struct SweepStats {
    files: usize,
    archives: usize,
    members: usize,
    objects: usize,
    bigobj: usize,
    short_imports: usize,
    long_import_symbols: usize,
    long_import_unresolved: usize,
    images: usize,
    exports: usize,
    defs: usize,
    other: usize,
    errors: Vec<String>,
}

fn sweep_roots() -> Vec<PathBuf> {
    let mut roots: Vec<PathBuf> = [
        "/usr/x86_64-w64-mingw32",
        "/usr/i686-w64-mingw32",
        "/usr/lib/gcc/x86_64-w64-mingw32",
        "/usr/lib/gcc/i686-w64-mingw32",
        "/usr/lib/mingw64-toolchain",
        "/usr/lib/mingw32-toolchain",
    ]
    .iter()
    .map(PathBuf::from)
    .collect();
    for compiler in ["x86_64-w64-mingw32-gcc", "i686-w64-mingw32-gcc"] {
        if let Ok(output) = Command::new(compiler).arg("-print-sysroot").output() {
            let sysroot = String::from_utf8_lossy(&output.stdout).trim().to_owned();
            if !sysroot.is_empty() {
                roots.push(PathBuf::from(sysroot));
            }
        }
    }
    if let Some(extra) = std::env::var_os("QLD_COFF_SWEEP_DIRS") {
        roots.extend(std::env::split_paths(&extra));
    }
    roots.retain(|r| r.is_dir());
    roots.sort();
    roots.dedup();
    // Drop roots nested in other roots.
    let all = roots.clone();
    roots.retain(|r| !all.iter().any(|o| o != r && r.starts_with(o)));
    roots
}

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(kind) = entry.file_type() else {
            continue;
        };
        if kind.is_dir() {
            walk(&path, out);
        } else if kind.is_file()
            && path.extension().and_then(|e| e.to_str()).is_some_and(|e| {
                matches!(
                    e.to_ascii_lowercase().as_str(),
                    "a" | "lib" | "rlib" | "o" | "obj" | "dll" | "exe" | "def"
                )
            })
        {
            out.push(path);
        }
    }
}

fn sweep_one(name: &str, data: &[u8], stats: &mut SweepStats) {
    use qld::input::FileFormat;
    // Only what the input layer identifies as PE/COFF comes to this reader.
    if !matches!(
        qld::input::identify(data),
        FileFormat::Coff(_) | FileFormat::CoffImport(_) | FileFormat::Pe(_)
    ) {
        stats.other += 1;
        return;
    }
    let path = Path::new(name);
    let parsed = CoffFile::parse(data, source(path));
    match parsed {
        Ok(CoffFile::Object(object)) => {
            stats.objects += 1;
            stats.bigobj += usize::from(object.is_bigobj());
            let before = stats.errors.len();
            let mut check = |r: Result<(), qld::Error>| {
                if let Err(e) = r {
                    stats.errors.push(format!("{name}: {e}"));
                }
            };
            check((|| {
                for section in object.sections() {
                    let section = section?;
                    object.section_data(&section.header)?;
                    for reloc in object.relocations(&section.header)?.iter() {
                        object.symbol(reloc.symbol_table_index)?;
                    }
                }
                for symbol in object.symbols().iter() {
                    symbol?;
                }
                for directives in object.directives() {
                    for directive in directives? {
                        directive?;
                    }
                }
                object.feat00()?;
                Ok(())
            })());
            if stats.errors.len() == before
                && let Err(e) = classify_long_import(&object)
            {
                stats.errors.push(format!("{name}: {e}"));
            }
        }
        Ok(CoffFile::ShortImport(_)) => stats.short_imports += 1,
        Ok(CoffFile::Image(image)) => {
            stats.images += 1;
            match image.exports() {
                Ok(Some(exports)) => match exports.all() {
                    Ok(all) => {
                        stats.exports += all.len();
                        // Stand-alone DLLs with exports: check them against
                        // llvm-readobj too.
                        if !all.is_empty() && Path::new(name).is_file() {
                            compare_exports_with_readobj(path, &image);
                        }
                    }
                    Err(e) => stats.errors.push(format!("{name}: {e}")),
                },
                Ok(None) => {}
                Err(e) => stats.errors.push(format!("{name}: {e}")),
            }
        }
        Err(e) => stats.errors.push(format!("{name}: {e}")),
    }
}

#[test]
#[ignore = "slow: sweeps the MinGW sysroot"]
fn sweep_mingw_sysroot() {
    let roots = sweep_roots();
    if roots.is_empty() {
        skip("no MinGW sysroot found");
        return;
    }
    let mut files = Vec::new();
    for root in &roots {
        walk(root, &mut files);
    }
    files.sort();
    let mut stats = SweepStats::default();
    for path in &files {
        let Ok(data) = std::fs::read(path) else {
            continue;
        };
        stats.files += 1;
        let name = path.display().to_string();
        if path.extension().is_some_and(|e| e == "def") {
            // GCC's plugin headers use `.def` for C include files.
            let looks_like_def = [&b"EXPORTS"[..], b"LIBRARY", b"NAME"]
                .iter()
                .any(|k| data.windows(k.len()).any(|w| w == *k));
            if path.components().any(|c| c.as_os_str() == "include") || !looks_like_def {
                stats.other += 1;
            } else if let Err(e) = parse_module_definition(&data, source(path)) {
                stats.errors.push(format!("{name}: {e}"));
            } else {
                stats.defs += 1;
            }
            continue;
        }
        if data.starts_with(b"!<arch>\n") {
            stats.archives += 1;
            let archive = match Archive::parse(path, &data) {
                Ok(archive) => archive,
                Err(e) => {
                    stats.errors.push(format!("{name}: {e}"));
                    continue;
                }
            };
            let mut dlls = LongImportDlls::new();
            let mut pending = Vec::new();
            let mut objects = Vec::new();
            for member in archive.members() {
                let member = match member {
                    Ok(member) => member,
                    Err(e) => {
                        stats.errors.push(format!("{name}: {e}"));
                        break;
                    }
                };
                let Some(bytes) = member.bytes() else {
                    continue;
                };
                stats.members += 1;
                let member_name = format!("{name}({})", member.display_name());
                sweep_one(&member_name, bytes, &mut stats);
                if let Ok(object) = CoffObject::parse(bytes, source(path)) {
                    objects.push(object);
                }
            }
            for object in &objects {
                if let Ok(Some(member)) = classify_long_import(object) {
                    dlls.add(&member);
                    if let LongImportMember::Symbol(symbol) = member {
                        pending.push(symbol.head_symbol);
                    }
                }
            }
            stats.long_import_symbols += pending.len();
            let unresolved = pending
                .iter()
                .filter(|head| dlls.dll_name(head).is_none())
                .count();
            if unresolved != 0 {
                stats
                    .errors
                    .push(format!("{name}: {unresolved} long imports without a DLL"));
            }
            stats.long_import_unresolved += unresolved;
        } else {
            sweep_one(&name, &data, &mut stats);
        }
    }
    println!("roots: {roots:?}");
    println!(
        "files {} (archives {}, members {}): objects {} (bigobj {}), short imports {}, \
         long import symbols {} (unresolved {}), images {} with {} exports, .def files {}, \
         other {}",
        stats.files,
        stats.archives,
        stats.members,
        stats.objects,
        stats.bigobj,
        stats.short_imports,
        stats.long_import_symbols,
        stats.long_import_unresolved,
        stats.images,
        stats.exports,
        stats.defs,
        stats.other
    );
    for error in stats.errors.iter().take(50) {
        println!("error: {error}");
    }
    assert!(stats.errors.is_empty(), "{} errors", stats.errors.len());
}
